mapper.select:
select o.object_id, o.object_code, o.object_name, o.object_type, o.template_id, o.template_code, o.template_name, o.bone_rfid_id, o.bone_rfid_code, o.bind_status, o.lifecycle_status, o.owner_user_id, o.owner_user_name, o.source_system, o.search_text, o.fixed_data::text as fixed_data_json, o.dynamic_data::text as dynamic_data_json, o.trace_data::text as trace_data_json, o.ext_data::text as ext_data_json, o.bind_time, o.unbind_time, o.completed_time, br.status as bone_status, o.del_flag, o.create_by, o.create_time, o.update_by, o.update_time, o.remark from "object" o left join bone_rfid br on br.bone_rfid_id = o.bone_rfid_id
and o.del_flag = '0' and o.object_code like concat('%', #{objectCode}, '%') and o.object_name like concat('%', #{objectName}, '%') and o.object_type = #{objectType} and o.bind_status = #{bindStatus} and o.owner_user_id = #{ownerUserId}
order by o.object_id desc
